// AWI: pulihkan rep_fields TiTAN + cek template tema (sementara, hapus setelah dipakai)
add_action('rest_api_init', function () {
	register_rest_route('awi/v1', '/tfix6', array(
		'methods' => 'POST',
		'permission_callback' => function () { return current_user_can('manage_options'); },
		'callback' => function () {
			$out = array('del' => delete_post_meta(10706, 'rep_fields'));
			$dir = get_template_directory();
			$it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir, FilesystemIterator::SKIP_DOTS));
			foreach ($it as $f) {
				if (substr($f, -4) !== '.php') continue;
				$s = file_get_contents($f);
				$o = 0;
				while (($i = strpos($s, 'pricem', $o)) !== false) { $out['hits'][] = str_replace($dir, '', $f) . ' @' . $i . ': ' . substr($s, max(0, $i - 300), 520); $o = $i + 6; if (count($out['hits']) > 8) break 2; }
			}
			$out['child'] = get_stylesheet_directory();
			wp_cache_flush();
			do_action('litespeed_purge_all');
			return $out;
		},
	));
});
